import React, { useState, useEffect, useRef } from 'react';
import io from 'socket.io-client';
import './App.css';
import SidebarLayout from './layouts/SidebarLayout';
import DiscoverWrapper from './pages/DiscoverWrapper';
import Dashboard from './pages/Dashboard';
import NearbyMap from './pages/NearbyMap';
import PassportMode from './pages/PassportMode';
import NotificationCenter from './components/NotificationCenter';
import DiscoverySettings from './pages/DiscoverySettings';
import SearchMatches from './pages/SearchMatches';
import { useWebSocket } from './hooks/useWebSocket';
import { Eye, EyeOff, Trash2 } from 'react-feather';
const backendHost = window.location.hostname === 'localhost' ? 'localhost' : window.location.hostname;
const API_BASE = `http://${backendHost}:5000/api/user`;
const AUTH_API_BASE = `http://${backendHost}:5000/api/auth`;

const fixImageUrl = (url) => {
  if (!url) return url;
  if (url.includes('/static/uploads/')) {
    const path = url.substring(url.indexOf('/static/uploads/'));
    const backendHost = window.location.hostname === 'localhost' ? 'localhost' : window.location.hostname;
    return `http://${backendHost}:5000${path}`;
  }
  if (url.includes('localhost:5000') && window.location.hostname !== 'localhost') {
    return url.replace('localhost:5000', `${window.location.hostname}:5000`);
  }
  return url;
};

// ============================================
// KENYAN COUNTIES AND TOWNS DATA
// ============================================
const KENYAN_COUNTIES = [
  'Baringo', 'Bomet', 'Bungoma', 'Busia', 'Elgeyo Marakwet', 'Embu', 'Garissa', 
