      c.phone === contact.phone ? { ...c, unread: 0 } : c
    ));

    // Fetch message history from backend
    try {
      const phone = currentUser?.phone || myPhone;
      const res = await fetch(`${API_BASE}/${phone}/messages`);
      const data = await res.json();
      if (data.success && data.data) {
        const contactMsgs = data.data.filter(m => m.sender_phone === contact.phone || m.receiver_phone === contact.phone)
          .sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp))
          .map(m => {
            let msgContent = m.content || '';
            let msgMediaUrl = m.media_url;

            if (!msgMediaUrl && msgContent.includes('/static/uploads/')) {
              msgMediaUrl = msgContent;
              msgContent = '';
            }

            return {
              id: m.id,
              sender: m.sender_phone === phone ? 'You' : contact.name,
              message: msgContent,
              media_url: fixImageUrl(msgMediaUrl),
              time: new Date(m.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
              isMine: m.sender_phone === phone,
              status: 'sent'
            };
          });

        setChatMessages(prev => ({
