                    value={formData[field.key] || ''}
                    onChange={(e) => handleInputChange(field.key, e.target.value)}
                    placeholder={field.placeholder}
                    className="input-field"
                  />
                )}
              </div>
            ))}
          </div>

          <div className="registration-actions landscape-actions">
            <button
              onClick={saveCompleteProfile}
              disabled={isLoading}
              className="btn-save-profile"
            >
              {isLoading ? '⏳ Saving...' : 'Continue'}
            </button>
            <button
              onClick={() => {
                addNotification('⏭️ Profile skipped. You can complete it later.');
                addToConversation('📱 You', 'details#(skipped)', false);
                addToConversation('🤖 System', SYSTEM_MESSAGES.detailsNotProvided, true);
                setSystemResponseMessage(SYSTEM_MESSAGES.detailsNotProvided);
                setShowSystemResponse(true);
                setCurrentStep(4);
                setIsCompleteProfileStep(false);
              }}
              className="btn-skip"
            >
              Skip
            </button>
            <button onClick={handleLogout} className="btn-exit">
              Exit
            </button>
          </div>

          <div className="registration-footer">
            <p>🔒 Your data is safe and private</p>
          </div>
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER REGISTRATION STEPS (Redesigned 3-Step Flow)
  // ============================================
  const renderRegistrationStep = () => {
    // We map internal currentStep (which starts at 1 from activation, or 0) 
    // Let's normalize it for the 3-step UI
    // If currentStep is 1 -> UI Step 1 (Basic Info)
    // If currentStep is 2 -> UI Step 2 (Details)
    // If currentStep is 3 -> UI Step 3 (Description)
    // If currentStep is 4 -> Success
    const uiStep = currentStep === 0 ? 1 : currentStep;
    const isSuccessScreen = uiStep >= 4;

    const handleFormSubmit = async () => {
      // Step 1 Validation & API Call
      if (uiStep === 1) {
        if (!formData.name || formData.name.trim().length < 2) {
          setRegistrationError("Please enter your full name (minimum 2 characters)");
          return;
        }
        if (!formData.age || parseInt(formData.age) < 18) {
          setRegistrationError("You must be 18 or older to use this service");
          return;
        }
        if (!formData.gender) {
          setRegistrationError("Please select your gender");
          return;
        }
        if (!formData.county) {
          setRegistrationError("Please select your county");
          return;
        }
        if (!formData.town || (formData.town === 'Other' && (!formData.town_other || formData.town_other.trim() === ''))) {
          setRegistrationError("Please enter your town/city");
          return;
        }
        if (!formData.phone_number || !validateKenyanPhone(formData.phone_number.trim())) {
          setRegistrationError("Please enter a valid Kenyan phone number (e.g. 0712345678).");
          return;
        }
        if (!formData.password || formData.password.length < 10) {
          setRegistrationError("Password must be at least 10 characters.");
          return;
        }

        setRegistrationError('');
        setIsLoading(true);
        try {
          const data = {
            phone_number: formData.phone_number,
            name: formData.name,
            password: formData.password,
            age: formData.age,
            gender: formData.gender,
            county: formData.county,
            town: formData.town === 'Other' ? formData.town_other.trim() : formData.town
          };
          const result = await callApi('/register', 'POST', data);

          if (result && result.status === 'error' && result.message === 'User already exists') {
            setRegistrationError('⚠️ An account already exists with this phone number.');
            setUserExistsError(true);
            setIsLoading(false);
            return;
          }

          if (result && result.status === 'success') {
            setMyPhone(formData.phone_number);
            const newUser = { phone: formData.phone_number, name: formData.name, age: formData.age, gender: formData.gender, county: formData.county, town: formData.town };
            setCurrentUser(newUser);
            setSystemResponseMessage(`💬 Your profile has been created successfully, ${formData.name}! Now, tell us more about yourself.`);
            setCurrentStep(2);
            setIsLoading(false);
            return;
          } else {
            setRegistrationError(result?.message || 'Registration failed. Please try again.');
            setIsLoading(false);
            return;
          }
        } catch (error) {
          setRegistrationError('Network error. Please try again.');
          setIsLoading(false);
          return;
        }
      }

      // Step 2 Validation & UI Progress
      // Step 2 Validation & UI Progress
      if (uiStep === 2) {
        if (!formData.education || (formData.education === 'Other' && !formData.education_other)) {
          setRegistrationError("Please select your education level");
          return;
        }
        if (!formData.profession || formData.profession.length < 2) {
          setRegistrationError("Please enter your profession");
          return;
        }
        if (!formData.marital_status) {
          setRegistrationError("Please select your marital status");
          return;
        }
        if (!formData.religion || (formData.religion === 'Other' && !formData.religion_other)) {
          setRegistrationError("Please select your religion");
          return;
        }
        if (!formData.ethnicity || (formData.ethnicity === 'Other' && !formData.ethnicity_other)) {
          setRegistrationError("Please select your ethnicity");
          return;
        }

        setRegistrationError('');
        setIsLoading(true);
        try {
          const phone = currentUser?.phone || myPhone;
          const data = {
            education_level: formData.education === 'Other' ? formData.education_other : formData.education,
            profession: formData.profession,
            marital_status: formData.marital_status,
            religion: formData.religion === 'Other' ? formData.religion_other : formData.religion,
            ethnicity: formData.ethnicity === 'Other' ? formData.ethnicity_other : formData.ethnicity,
          };

          const result = await callApi(`/${phone}/complete-profile`, 'POST', data);

          if (result && result.status === 'success') {
            setCurrentStep(3);
            setSystemResponseMessage(`✨ Almost there! How would you describe yourself in a few words?\n(e.g., chocolate, lovely, sexy)`);
            setIsLoading(false);
            return;
          } else {
            setRegistrationError(result?.message || 'Failed to save details. Please try again.');
            setIsLoading(false);
            return;
          }
        } catch (error) {
          setRegistrationError('Network error. Please try again.');
          setIsLoading(false);
          return;
        }
      }

      // Step 3 Validation & API Call
      if (uiStep === 3) {
        if (!formData.description || formData.description.length < 10) {
          setRegistrationError("Please describe yourself (minimum 10 characters)");
          return;
        }

        setIsLoading(true);
        try {
          const phone = currentUser?.phone || myPhone;
          // Note: In a real app we'd send the step 2 data to a details endpoint, but for this task we follow existing API limits or assume self-description completes it.
          const result = await callApi(`/${phone}/self-description`, 'POST', { 
            description: formData.description 
          });

          if (result && result.status === 'success') {
            setRegistrationComplete(true);
            setCurrentStep(4);
            setIsLoading(false);
            return;
          } else {
            setRegistrationError(result?.message || 'Self-description failed.');
            setIsLoading(false);
            return;
          }
        } catch (error) {
          setRegistrationError('Network error. Please try again.');
          setIsLoading(false);
          return;
        }
      }
    };

    if (isSuccessScreen) {
      return (
        <div className="registration-v2-container">
          <div className="registration-v2-card reg-v2-success">
            <div className="reg-v2-heart">❤️</div>
