              GO TO DASHBOARD
            </button>
          </div>
        </div>
      );
    }

    const stepTitles = {
      1: 'Create Your Dating Profile',
      2: 'Additional Details',
      3: 'Self-Description'
    };

    return (
      <div className="registration-v2-container">
        <div className="registration-v2-card">
          <div className="reg-v2-header">
            {uiStep > 1 && (
              <button className="reg-v2-back" onClick={() => setCurrentStep(uiStep - 1)}>
