            <h1 className="reg-v2-title" style={{ marginLeft: uiStep === 1 ? 'auto' : '0' }}>
              {stepTitles[uiStep]}
            </h1>
            {uiStep === 1 && <div style={{width: '60px'}}></div>}
          </div>

          <div className="reg-v2-progress">
            {[1, 2, 3].map(num => (
              <div key={num} className={`reg-v2-step ${uiStep >= num ? 'active' : ''}`}></div>
            ))}
          </div>
          <div className="reg-v2-step-labels">
            <span>Basic Info</span>
            <span>Details</span>
            <span>Description</span>
          </div>

          {uiStep > 1 && systemResponseMessage && (
