                className="modal-overlay" 
                style={{
                  zIndex: 9999,
                  backgroundColor: 'rgba(255, 255, 255, 0.4)',
                  backdropFilter: 'blur(12px)',
                  WebkitBackdropFilter: 'blur(12px)',
                  display: 'flex',
                  justifyContent: 'center',
                  alignItems: 'center',
                  animation: 'penziModalFadeIn 0.4s ease-out forwards'
                }}
