                <div 
                  className="modal-content" 
                  style={{
                    textAlign: 'center', 
                    padding: '40px 32px', 
                    width: '90%',
                    maxWidth: '420px', 
                    backgroundColor: '#ffffff', 
                    borderRadius: '32px',
                    boxShadow: '0 30px 60px -12px rgba(128, 0, 32, 0.15), 0 0 0 1px rgba(128, 0, 32, 0.05)',
                    animation: 'penziModalSlideUp 0.5s cubic-bezier(0.2, 0.8, 0.2, 1) forwards'
                  }}
                >
                  <div style={{
                    width: '72px',
