          {/* STEP 1 FIELDS */}
          {uiStep === 1 && (
            <div className="reg-v2-form-grid">
              <div className="reg-v2-form-group">
                <label className="reg-v2-label">Phone Number<span className="req">*</span></label>
                <input 
                  className="reg-v2-input" 
                  type="tel" 
                  autoComplete="off"
                  placeholder="Enter phone number" 
                  value={formData.phone_number || ''} 
                  onChange={e => handleInputChange('phone_number', e.target.value)} 
                />
              </div>
              <div className="reg-v2-form-group">
                <label className="reg-v2-label">Password<span className="req">*</span></label>
                <div style={{ position: 'relative' }}>
                  <input 
                    className="reg-v2-input password-input-no-reveal" 
                    type={showRegisterPassword ? "text" : "password"} 
                    autoComplete="new-password"
                    placeholder="Enter password" 
                    value={formData.password || ''} 
                    onChange={e => handleInputChange('password', e.target.value)} 
                  />
                  <button
                    type="button"
                    onClick={() => setShowRegisterPassword(!showRegisterPassword)}
                    style={{
                      position: 'absolute',
                      right: '16px',
                      top: '50%',
                      transform: 'translateY(-50%)',
                      background: 'none',
                      border: 'none',
                      cursor: 'pointer',
                      fontSize: '13px',
                      fontWeight: '600',
                      color: '#800020',
                      padding: '4px'
                    }}
                    title={showRegisterPassword ? "Hide password" : "Show password"}
                  >
                    {showRegisterPassword ? 'Hide' : '👁️'}
                  </button>
                </div>
              </div>
              <div className="reg-v2-form-group">
                <label className="reg-v2-label">Full Name<span className="req">*</span></label>
                <input 
                  className="reg-v2-input" 
                  type="text" 
                  placeholder="Enter full name" 
                  value={formData.name || ''} 
                  onChange={e => handleInputChange('name', e.target.value)} 
                />
              </div>
              <div className="reg-v2-form-group">
                <label className="reg-v2-label">Age<span className="req">*</span></label>
                <input 
                  className="reg-v2-input" 
                  type="number" 
                  min="18"
                  placeholder="Enter age" 
                  value={formData.age || ''} 
                  onChange={e => handleInputChange('age', e.target.value)} 
                />
              </div>
              <div className="reg-v2-form-group">
                <label className="reg-v2-label">Gender<span className="req">*</span></label>
                <div className="reg-v2-segmented">
                  {['Male', 'Female'].map(g => (
                    <button 
                      key={g}
                      className={`reg-v2-segment-btn ${formData.gender === g ? 'active' : ''}`}
                      onClick={() => handleInputChange('gender', g)}
                    >
                      {g}
                    </button>
                  ))}
                </div>
              </div>
              <div className="reg-v2-form-group">
                <label className="reg-v2-label">County<span className="req">*</span></label>
                <select 
                  className="reg-v2-select" 
                  value={formData.county || ''} 
                  onChange={e => {
                    handleInputChange('county', e.target.value);
                    handleInputChange('town', '');
                  }}
                >
                  <option value="">Select your county</option>
                  {KENYAN_COUNTIES.map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div className="reg-v2-form-group">
                <label className="reg-v2-label">Town/City<span className="req">*</span></label>
                <select 
                  className="reg-v2-select" 
                  value={formData.town || ''} 
                  onChange={e => handleInputChange('town', e.target.value)}
                  disabled={!formData.county}
                >
                  <option value="">{formData.county ? 'Select your town' : 'Select county first'}</option>
                  {(KENYAN_TOWNS[formData.county] || []).map(t => <option key={t} value={t}>{t}</option>)}
                  {formData.county && <option value="Other">Other</option>}
                </select>
                {formData.town === 'Other' && (
                  <div className="slide-down-enter-active" style={{marginTop: '10px'}}>
                    <input className="reg-v2-input" type="text" placeholder="Specify your town or city" value={formData.town_other || ''} onChange={e => handleInputChange('town_other', e.target.value)} />
                  </div>
                )}
              </div>
            </div>
          )}

          {/* STEP 2 FIELDS */}
          {uiStep === 2 && (
            <div className="reg-v2-form-grid">
              <div className="reg-v2-form-group">
                <label className="reg-v2-label">Level of Education<span className="req">*</span></label>
                <select 
                  className="reg-v2-select" 
                  value={formData.education || ''} 
                  onChange={e => handleInputChange('education', e.target.value)}
                >
                  <option value="">Select education</option>
                  {['Secondary', 'Diploma', 'Graduate', 'Masters', 'PhD', 'Other'].map(o => <option key={o} value={o}>{o}</option>)}
                </select>
                {formData.education === 'Other' && (
                  <div className="slide-down-enter-active">
                    <input className="reg-v2-input" type="text" placeholder="Specify your education" value={formData.education_other || ''} onChange={e => handleInputChange('education_other', e.target.value)} />
                  </div>
                )}
              </div>
              <div className="reg-v2-form-group">
                <label className="reg-v2-label">Profession<span className="req">*</span></label>
                <input 
                  className="reg-v2-input" 
                  type="text" 
                  placeholder="Enter profession" 
                  value={formData.profession || ''} 
                  onChange={e => handleInputChange('profession', e.target.value)} 
                />
              </div>
              <div className="reg-v2-form-group">
                <label className="reg-v2-label">Religion<span className="req">*</span></label>
                <select 
                  className="reg-v2-select" 
                  value={formData.religion || ''} 
                  onChange={e => handleInputChange('religion', e.target.value)}
                >
                  <option value="">Select religion</option>
                  {['Christian', 'Muslim', 'Hindu', 'Other'].map(o => <option key={o} value={o}>{o}</option>)}
                </select>
                {formData.religion === 'Other' && (
                  <div className="slide-down-enter-active">
                    <input className="reg-v2-input" type="text" placeholder="Specify your religion" value={formData.religion_other || ''} onChange={e => handleInputChange('religion_other', e.target.value)} />
                  </div>
                )}
              </div>
              <div className="reg-v2-form-group">
                <label className="reg-v2-label">Ethnicity<span className="req">*</span></label>
                <select 
                  className="reg-v2-select" 
                  value={formData.ethnicity || ''} 
                  onChange={e => handleInputChange('ethnicity', e.target.value)}
                >
                  <option value="">Select ethnicity</option>
                  {['Kikuyu', 'Luhya', 'Kalenjin', 'Luo', 'Kamba', 'Somali', 'Kisii', 'Mijikenda', 'Meru', 'Other'].map(o => <option key={o} value={o}>{o}</option>)}
