    setShowDeleteMsgModal(true);
  };

  // Confirms and executes delete
  const confirmDeleteMessage = async () => {
    if (!pendingDeleteMsgId) return;
    setIsDeletingMessage(true);
    try {
      const fromPhone = currentUser?.phone;
      const response = await fetch(`${API_BASE}/${fromPhone}/messages/${pendingDeleteMsgId}`, {
        method: 'DELETE',
      });
      if (response.ok) {
        setChatMessages(prev => {
          const newChats = { ...prev };
          if (newChats[selectedChatContact?.phone]) {
            newChats[selectedChatContact.phone] = newChats[selectedChatContact.phone].filter(
              m => m.id !== pendingDeleteMsgId
            );
          }
          return newChats;
        });
        addNotification('🗑️ Message deleted.', 'success');
      } else {
        addNotification('❌ Failed to delete message.', 'error');
      }
    } catch (e) {
      console.error(e);
      addNotification('❌ Error deleting message.', 'error');
    } finally {
      setIsDeletingMessage(false);
      setShowDeleteMsgModal(false);
      setPendingDeleteMsgId(null);
    }
  };

