  const handleDeleteChat = async () => {
    if (!window.confirm("Delete this entire conversation?")) return;
    try {
      const fromPhone = currentUser?.phone;
      const response = await fetch(`${API_BASE}/${fromPhone}/messages/chat/${selectedChatContact.phone}`, {
        method: 'DELETE',
      });
      if (response.ok) {
        setChatMessages(prev => ({...prev, [selectedChatContact.phone]: []}));
        setChatContacts(prev => prev.filter(c => c.phone !== selectedChatContact.phone));
        setSelectedChatContact(null);
      } else {
        alert("Failed to delete chat");
      }
    } catch (e) {
      console.error(e);
      alert("Error deleting chat");
    }
  };

  const renderChat = () => {
