          <div className="table-header-left">
            <h3>💕 Your Matches</h3>
            <span className="match-count">{myMatches.length} matches</span>
          </div>
        </div>

        <div className="matches-grid">
          {myMatches.map((match, index) => (
            <div key={match.id} className="user-card">
              <div 
                className="user-card-avatar" 
                onClick={(e) => { e.stopPropagation(); if (match.profile_picture_url) setFullscreenImage(match.profile_picture_url); else viewProfile(match); }} 
                style={match.profile_picture_url ? { backgroundImage: `url(${match.profile_picture_url})`, backgroundSize: 'cover', backgroundPosition: 'center' } : {}}
              >
                {match.profile_picture_url ? '' : (match.name?.charAt(0) || '?')}
              </div>
              <div className="user-card-info" onClick={() => viewProfile(match)}>
                <div className="user-card-name">{match.name} <span className="status-accepted" style={{fontSize:'12px', marginLeft:'4px'}}>✅</span></div>
                <div className="user-card-age">{match.age} years old</div>
              </div>
              <div className="user-card-actions">
                <button className="btn-view" onClick={() => viewProfile(match)} title="View Profile">👁</button>
                <button className="btn-chat" onClick={() => startChat(match)} title="Start Chat">💬</button>
                <button className="btn-describe" onClick={() => getDescription(match.phone || match.phone_number)} title="Get Description">📝</button>
              </div>
            </div>
          ))}
        </div>

        <div className="table-navigation">
          <button 
            className="nav-btn"
            onClick={() => setCurrentMatchListIndex(Math.max(0, currentMatchListIndex - 5))}
            disabled={currentMatchListIndex === 0}
          >
            ⬅ Previous
          </button>
          <span className="match-counter">
            {currentMatchListIndex + 1} of {myMatches.length}
          </span>
          <button 
            className="nav-btn"
            onClick={() => setCurrentMatchListIndex(Math.min(myMatches.length - 1, currentMatchListIndex + 5))}
            disabled={currentMatchListIndex >= myMatches.length - 1}
          >
            Next ➡
          </button>
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER STATS CLICK HANDLERS
  // ============================================
  const handleStatClick = (statType) => {
    setShowMainMenu(false);
    switch(statType) {
      case 'totalMatches':
        setActiveTab('discover');
        addNotification('👥 Showing all matches');
        break;
      case 'pendingRequests':
        setActiveTab('requests');
        addNotification('📬 Showing pending requests');
        break;
      case 'acceptedMatches':
        setActiveTab('matches');
        addNotification('💕 Showing accepted matches');
        break;
      case 'unreadMessages':
        setActiveTab('chat');
        addNotification('💬 Showing unread messages');
        break;
      default:
        break;
    }
  };

  // ============================================
  // RENDER MAIN MENU
  // ============================================
  const renderMainMenu = () => {
    const hasProfile = completedSteps.has(1);
    const hasDescription = completedSteps.has(2);

    return (
      <div className="main-menu-container">
        <div className="main-menu-header">
          <h1>💑 PENZI Dating</h1>
          <p className="menu-subtitle">Welcome back. Choose one of the options below.</p>
          {currentUser && (
            <div className="menu-user-info">
              <span>👋 Welcome, {currentUser.name || 'User'}!</span>
            </div>
          )}
        </div>

        {/* dashboard-stats removed and integrated into cards below */}

        <div className="main-menu-options">
          <div className="menu-card profile-card" onClick={() => {
            setShowMainMenu(false);
            setActiveTab('discover');
            setShowProfile(true);
            setIsEditingProfile(false);
          }}>
            <div className="menu-card-icon">👤</div>
            <div className="menu-card-content">
              <h3>My Profile</h3>
              <p>View and edit your profile</p>
              {hasProfile && hasDescription && <span className="menu-card-badge">✅ Complete</span>}
              {(!hasProfile || !hasDescription) && <span className="menu-card-badge inactive">⏳ Incomplete</span>}
            </div>
          </div>

          <div className="menu-card matches-card" onClick={() => {
            setShowMainMenu(false);
            setActiveTab('discover');
            if (allMatches.length === 0) {
              const userGender = currentUser?.gender;
              let sampleData = [];

              if (userGender && userGender.toLowerCase() === 'male') {
                sampleData = SAMPLE_MATCHES;
              } else if (userGender && userGender.toLowerCase() === 'female') {
                sampleData = SAMPLE_MALE_MATCHES;
              } else {
                sampleData = [...SAMPLE_MATCHES, ...SAMPLE_MALE_MATCHES];
              }

              setAllMatches(sampleData.slice(0, 3));
              setMatchResults(sampleData);
              setHasMoreMatches(sampleData.length > 3);
              setMatchSearchActive(true);
              addNotification(`✅ Found ${sampleData.length} matches!`);
            }
          }}>
            <div className="menu-card-icon">❤️</div>
            <div className="menu-card-content">
              <h3>Search Matches</h3>
              <p>Find your perfect partner</p>
              <div className="menu-card-inline-stats">
                <span className="inline-stat" onClick={(e) => { e.stopPropagation(); handleStatClick('totalMatches'); }}>👥 {stats.totalMatches} Total Matches</span>
                <span className="inline-stat" onClick={(e) => { e.stopPropagation(); handleStatClick('acceptedMatches'); }}>💕 {stats.acceptedMatches} Accepted</span>
              </div>
            </div>
          </div>

          <div className="menu-card requests-card" onClick={() => {
            setShowMainMenu(false);
            setActiveTab('requests');
            if (incomingRequests.length === 0) {
              setIncomingRequests(SAMPLE_REQUESTS);
            }
          }}>
            <div className="menu-card-icon">💌</div>
            <div className="menu-card-content">
              <h3>My Requests</h3>
              <p>People interested in you</p>
              <div className="menu-card-inline-stats">
                <span className="inline-stat">📬 {stats.pendingRequests} Pending Requests</span>
                <span className="inline-stat">🎯 {stats.pendingRequests} Total Requests</span>
              </div>
              {stats.pendingRequests > 0 && <span className="menu-card-badge">{stats.pendingRequests} new</span>}
            </div>
          </div>

          <div className="menu-card chat-card" onClick={() => {
            setShowMainMenu(false);
            setActiveTab('chat');
          }}>
            <div className="menu-card-icon">💬</div>
            <div className="menu-card-content">
              <h3>Chats</h3>
              <p>Your conversations</p>
              {stats.unreadMessages > 0 && <span className="menu-card-badge">{stats.unreadMessages} unread</span>}
            </div>
          </div>

          <div className="menu-card dashboard-card" onClick={() => {
            setShowMainMenu(false);
            setActiveTab('dashboard');
          }}>
            <div className="menu-card-icon">📊</div>
            <div className="menu-card-content">
              <h3>Admin Dashboard</h3>
              <p>RabbitMQ Live Activity Feed</p>
            </div>
          </div>

          <div className="menu-card map-card" onClick={() => {
            setShowMainMenu(false);
            setActiveTab('map');
          }}>
            <div className="menu-card-icon">📍</div>
            <div className="menu-card-content">
              <h3>Nearby Map</h3>
              <p>Discover people near your location</p>
            </div>
          </div>

          <div className="menu-card passport-card" onClick={() => {
            setShowMainMenu(false);
            setActiveTab('passport');
          }}>
            <div className="menu-card-icon">🌍</div>
            <div className="menu-card-content">
              <h3>Passport Mode</h3>
              <p>Change your virtual location</p>
            </div>
          </div>

          <div className="menu-card settings-card" onClick={() => {
            setShowMainMenu(false);
            setActiveTab('settings');
          }}>
            <div className="menu-card-icon">⚙️</div>
            <div className="menu-card-content">
              <h3>Settings</h3>
              <p>Discovery settings & privacy</p>
            </div>
          </div>

          <div className="menu-card logout-card" onClick={handleLogout}>
            <div className="menu-card-icon">🚪</div>
            <div className="menu-card-content">
              <h3>Logout</h3>
              <p>Exit the application</p>
            </div>
          </div>
        </div>

        <div className="main-menu-footer">
          <span className="menu-version">v2.0 • PENZI Dating Service</span>
          <span className="menu-version">🔒 Secure • Private</span>
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER DASHBOARD
  // ============================================
  const renderDashboard = () => {
    const hasRequests = incomingRequests.length > 0;
    const hasChatContacts = chatContacts.length > 0;

    if (showProfile || activeTab === 'profile') {
        return renderProfileDetails();
    }

    return (
      <SidebarLayout activeTab={activeTab} setActiveTab={setActiveTab} handleLogout={handleLogout}>
        <header className="dashboard-header" style={{ padding: '15px 30px', background: 'white', borderBottom: '1px solid #e5e7eb', display: 'flex', justifyContent: 'space-between', alignItems: 'center', height: '70px', boxSizing: 'border-box' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
            <h1 style={{ margin: 0, fontSize: '1.5rem', color: '#e11d48' }}>💑 PENZI</h1>
            <span className="live-badge" style={{ background: '#fee2e2', color: '#ef4444', padding: '4px 8px', borderRadius: '12px', fontSize: '0.8rem', fontWeight: 'bold' }}>❤️ Live</span>
          </div>
          <div className="header-right" style={{ display: 'flex', alignItems: 'center', gap: '15px' }}>
            <NotificationCenter />
            <span className="user-greeting" style={{ fontWeight: 'bold', color: '#4b5563' }}>👋 {currentUser?.name || 'User'}</span>
            <div 
              className="user-avatar" 
              onClick={() => { setShowProfile(true); setIsEditingProfile(false); }} 
              style={currentUser?.profile_picture_url ? { backgroundImage: `url(${currentUser.profile_picture_url})`, backgroundSize: 'cover', backgroundPosition: 'center', color: 'transparent', cursor: 'pointer', width:'40px', height:'40px', borderRadius:'50%' } : { cursor:'pointer', width:'40px', height:'40px', borderRadius:'50%', background:'#e11d48', color:'white', display:'flex', alignItems:'center', justifyContent:'center', fontWeight:'bold' }}
              title="My Profile"
            >
              {currentUser?.profile_picture_url ? '' : (currentUser?.name?.charAt(0) || '👤')}
            </div>
          </div>
        </header>

        <main className="dashboard-content" style={{ padding: '0', background: '#f3f4f6', height: 'calc(100vh - 70px)', display: 'flex', flexDirection: 'column' }}>
          {activeTab === 'dashboard' && <Dashboard 
            stats={stats} 
            notifications={notifications} 
            setActiveTab={setActiveTab} 
            currentUser={currentUser}
            allMatches={allMatches}
            myMatches={myMatches}
            startChat={(user) => { setSelectedChatContact(user); setActiveTab('chat'); }}
            handleExpressInterest={handleExpressInterest}
            viewUserProfile={viewUserProfile}
            onSearch={(criteria) => {
                setSearchCriteria(prev => ({ ...prev, ...criteria }));
                setActiveTab('search-matches');
            }}
          />}
          {activeTab === 'discover' && <DiscoverWrapper currentUser={currentUser} setActiveTab={setActiveTab} myMatches={myMatches} startChat={startChat} viewProfile={viewProfile} handleExpressInterest={handleExpressInterest} />}
          {activeTab === 'map' && <NearbyMap currentUser={currentUser} setActiveTab={setActiveTab} myMatches={myMatches} startChat={startChat} viewProfile={viewProfile} handleExpressInterest={handleExpressInterest} />}
          {activeTab === 'search-matches' && <SearchMatches 
            currentUser={currentUser} 
            myMatches={myMatches} 
            startChat={(user) => { setSelectedChatContact(user); setActiveTab('chat'); }} 
            handleExpressInterest={handleExpressInterest} 
            viewUserProfile={viewUserProfile} 
            initialSearchCriteria={searchCriteria} 
          />}
          {activeTab === 'passport' && <PassportMode currentUser={currentUser} setActiveTab={setActiveTab} />}
          {activeTab === 'settings' && <DiscoverySettings currentUser={currentUser} />}

          {/* Legacy Components */}
          {activeTab === 'matches' && <div style={{padding: '30px'}}>{renderMyMatchesTable()}</div>}
          {activeTab === 'requests' && <div style={{padding: '30px'}}>{renderRequestsTable()}</div>}
          {activeTab === 'sent-interests' && <div style={{padding: '30px'}}>{renderSentInterestsTable()}</div>}
          {activeTab === 'blocked-users' && (
            <div style={{padding: '30px', textAlign: 'center'}}>
              <h2>🚫 Blocked Users</h2>
              <p>Manage users you have blocked from contacting you.</p>
              <button className="btn-primary" onClick={() => setShowBlockedUsersModal(true)} style={{marginTop: '20px'}}>
                Open Blocked Users List
              </button>
            </div>
          )}

          {(activeTab === 'messages' || activeTab === 'chat') && (
            <div className="chat-container-whatsapp" style={{ height: 'calc(100vh - 70px)' }}>
              {renderChat()}
            </div>
          )}
        </main>

        {showMatchDetails && renderProfileModal()}
        {showProfile && renderProfileDetails()}
        {renderDescriptionModal()}
        {renderBlockModal()}
        {renderBlockedUsersModal()}
      </SidebarLayout>
    );
  };

  // ============================================
  // MAIN RETURN
  // ============================================
  // ============================================
  // FULLSCREEN IMAGE VIEWER
  // ============================================
  const renderFullscreenImageViewer = () => {
    if (!fullscreenImage) return null;

    return (
      <div 
        className="fullscreen-image-viewer" 
        onClick={() => setFullscreenImage(null)}
      >
        <button className="fullscreen-close" onClick={() => setFullscreenImage(null)}>✕</button>
        <img src={fullscreenImage} alt="Profile Fullscreen" onClick={(e) => e.stopPropagation()} />
      </div>
    );
  };

  return (
    <div className="app">
      {renderNotifications()}
      {renderLogoutModal()}
      {renderDeleteMessageModal()}
      {renderFullscreenImageViewer()}


      {/* Removed media-viewer-lite as per new in-place zoom design */}

      {showSuccessScreen ? (
        renderSuccessScreen()
      ) : userExistsError ? (
        renderUserExistsWarning()
      ) : showWelcomeBack && !isLoggedIn ? (
        renderWelcomeBack()
      ) : isLoggedIn ? (
        currentView === 'reactivation' ? renderReactivationPage() :
        showMainMenu ? renderMainMenu() : renderDashboard()
      ) : currentView === 'login' ? (
        renderLoginPage()
      ) : (
        /* Activation / Registration flow */
        activationDone ? (
          isCompleteProfileStep ? (
            renderCompleteProfile()
          ) : (
            renderRegistrationStep()
          )
        ) : (
          renderActivationPage()
        )
      )}
    </div>
  );
}

export default App;
